import 'dart:convert';

import 'package:chameleon/features/previews/frames_preview.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('reads a quality-90 JPEG: size and how hard it was compressed', () {
    final jpeg = readJpegInfo(base64Decode(''))!;
    expect((jpeg.width, jpeg.height), (24, 16));
    expect(jpeg.quantization, closeTo(11.5000, 0.001));
  });

  test('reads a quality-50 JPEG: size and how hard it was compressed', () {
    final jpeg = readJpegInfo(base64Decode(''))!;
    expect((jpeg.width, jpeg.height), (24, 16));
    expect(jpeg.quantization, closeTo(57.6250, 0.001));
  });

  test('not a JPEG', () => expect(readJpegInfo(utf8.encode('hello, world')), isNull));
}
